function SuperRareReward:Refresh(comp)
    if isNull(comp) then
        return
    end
    self.comp = comp
    
    local vo = self.comp:GetParamVo(7)
    if isNull(vo) then
        return
    end
    local rewardId = vo.num
    local vo = self.comp:GetParamVo(8)
    if isNull(vo) then
        return
    end
    local rewardNum = vo.num

    local rewardData = {
        id = rewardId,
        num = rewardNum,
    }

    local isGet = self.comp:GetSuperRareRewardIsGet()

    ---@type CommonGoodsListLight
    local scr = CfUtils.GetLuaScr(self.CommonGoodsListLight, "Game.Behaviours.CommonGoodsListLight")
    if isNotNull(scr) then
        scr:FreshBaseUI({rewardData}, false, isGet, nil, nil, nil, nil, false)
    end

    KTool.SetActive(self.UIFX_Glow, not isGet)
end

